import{_ as e}from"./chunks/grupos-e-subcategorias.CIp_CnkO.js";import{_ as o}from"./chunks/transacao.B5wN2nZn.js";import{_ as r}from"./chunks/recorrente-1._VkE8vJC.js";import{_ as s,a as t}from"./chunks/saldo-1.ukPh67mx.js";import{_ as i,c as n,ag as l,o as c}from"./chunks/framework.-a8jReyC.js";const C=JSON.parse('{"title":"Funcionalidades do FlyCash","description":"","frontmatter":{"title":"Funcionalidades do FlyCash"},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md"}'),u={name:"features/index.md"};function d(m,a,g,p,h,f){return c(),n("div",null,a[0]||(a[0]=[l('<h1 id="funcionalidades-do-flycash" tabindex="-1">Funcionalidades do FlyCash <a class="header-anchor" href="#funcionalidades-do-flycash" aria-label="Permalink to &quot;Funcionalidades do FlyCash&quot;">​</a></h1><p>Explore os recursos poderosos do FlyCash que ajudam você a gerenciar suas finanças de forma simples e eficiente. Seja você um leitor ou um aprendiz visual, temos tudo o que você precisa para dominar o aplicativo!</p><h2 id="📂-organizacao-por-grupos-e-categorias" tabindex="-1">📂 Organização por Grupos e Categorias <a class="header-anchor" href="#📂-organizacao-por-grupos-e-categorias" aria-label="Permalink to &quot;📂 Organização por Grupos e Categorias&quot;">​</a></h2><img src="'+e+'" width="600px"><h3 id="o-que-sao-grupos-e-categorias" tabindex="-1"><strong>O que são Grupos e Categorias?</strong> <a class="header-anchor" href="#o-que-sao-grupos-e-categorias" aria-label="Permalink to &quot;**O que são Grupos e Categorias?**&quot;">​</a></h3><p>Grupos e categorias são a base da organização no FlyCash. Eles permitem que você classifique suas transações de forma clara e intuitiva.</p><h4 id="exemplo-pratico" tabindex="-1"><strong>Exemplo Prático:</strong> <a class="header-anchor" href="#exemplo-pratico" aria-label="Permalink to &quot;**Exemplo Prático:**&quot;">​</a></h4><ol><li>Crie um grupo chamado <strong>Gastos</strong>.</li><li>Adicione categorias como <strong>Casa</strong>, <strong>Transporte</strong> e <strong>Lazer</strong>.</li><li>Dentro de <strong>Casa</strong>, crie subcategorias como <strong>Luz</strong>, <strong>Água</strong> e <strong>Internet</strong>.</li></ol><h4 id="por-que-usar" tabindex="-1"><strong>Por que usar?</strong> <a class="header-anchor" href="#por-que-usar" aria-label="Permalink to &quot;**Por que usar?**&quot;">​</a></h4><ul><li>Visualize claramente para onde seu dinheiro está indo.</li><li>Identifique áreas onde você pode economizar.</li></ul><p><a href="/features/groups-and-categories.html">Leia o guia completo sobre Grupos e Categorias</a></p><h2 id="✍️-transacoes-registro-manual" tabindex="-1">✍️ Transações (Registro Manual) <a class="header-anchor" href="#✍️-transacoes-registro-manual" aria-label="Permalink to &quot;✍️ Transações (Registro Manual)&quot;">​</a></h2><img src="'+o+'" width="600px"><h3 id="o-que-sao-transacoes" tabindex="-1"><strong>O que são Transações?</strong> <a class="header-anchor" href="#o-que-sao-transacoes" aria-label="Permalink to &quot;**O que são Transações?**&quot;">​</a></h3><p>Transações são movimentações financeiras que você faz com seus gastos e receitas. Você pode registrá-las <strong>manualmente</strong> a qualquer momento.</p><h4 id="como-configurar" tabindex="-1"><strong>Como configurar:</strong> <a class="header-anchor" href="#como-configurar" aria-label="Permalink to &quot;**Como configurar:**&quot;">​</a></h4><ol><li>Selecione um mês de referência em alguma categoria.</li><li>Clique no botão de <strong>Adicionar Transação</strong>.</li><li>Preencha os campos de <strong>Data</strong>, <strong>Valor</strong> e opcionalmente <strong>Descrição</strong>.</li><li>Clique no botão <strong>Salvar</strong>.</li></ol><p>Em cada transação você encontrará um botão de <strong>Configuração</strong> que permite editar o campo <strong>Status da Transação</strong> e <strong>Recebimento de lembrete para pagamento</strong>.</p><ul><li><strong>Status da Transação</strong>: Indica se a transação está <strong>paga</strong> ou <strong>pendente/atrasada</strong>.</li><li><strong>Recebimento de lembrete para pagamento</strong>: Indica se o lembrete de pagamento deve ser enviado para o email do destinatário. <ul><li>ℹ️ Essa opção serve apenas para informar a preferência do envio do lembrete de maneira individual. Para habilitar/desabilitar o envio de lembretes de pagamento em geral, vá em <a href="https://flyca.sh/profile" target="_blank" rel="noreferrer"><strong>Meu Perfil</strong></a> &gt; <strong>Configurações</strong> &gt; <strong>Recebimento de E-mails</strong>.</li></ul></li></ul><p><a href="/features/transactions.html">Leia o guia completo sobre Transações</a></p><h2 id="📥-importacao-de-faturas-pdf-ofx" tabindex="-1">📥 Importação de Faturas (PDF/OFX) <a class="header-anchor" href="#📥-importacao-de-faturas-pdf-ofx" aria-label="Permalink to &quot;📥 Importação de Faturas (PDF/OFX)&quot;">​</a></h2><p>Importe a fatura do seu cartão de crédito e ganhe tempo:</p><ul><li><strong>Formatos:</strong> PDF e OFX.</li><li><strong>Categorização automática:</strong> as transações entram com categorias sugeridas.</li><li><strong>Detecção de duplicatas:</strong> o sistema aponta compras que já existem no seu controle.</li><li><strong>Parcelas:</strong> compras parceladas são reconhecidas (ex: &quot;3/10&quot;) e projetadas nas próximas faturas.</li></ul><p><a href="/features/import-transactions.html">Leia o guia completo de Importação</a></p><h2 id="🔁-transacoes-recorrentes" tabindex="-1">🔁 Transações Recorrentes <a class="header-anchor" href="#🔁-transacoes-recorrentes" aria-label="Permalink to &quot;🔁 Transações Recorrentes&quot;">​</a></h2><img src="'+r+'" width="600px"><h3 id="o-que-sao-transacoes-recorrentes" tabindex="-1"><strong>O que são Transações Recorrentes?</strong> <a class="header-anchor" href="#o-que-sao-transacoes-recorrentes" aria-label="Permalink to &quot;**O que são Transações Recorrentes?**&quot;">​</a></h3><p>Transações recorrentes são movimentações que se repetem em intervalos regulares, como contas mensais ou salários.</p><h4 id="como-configurar-1" tabindex="-1"><strong>Como configurar:</strong> <a class="header-anchor" href="#como-configurar-1" aria-label="Permalink to &quot;**Como configurar:**&quot;">​</a></h4><ol><li>Marque uma transação como <strong>recorrente</strong>.</li><li>Defina a frequência (ex.: mensal) e o período de duração.</li><li>O FlyCash cria automaticamente as transações futuras.</li></ol><h4 id="gerenciamento-flexivel" tabindex="-1"><strong>Gerenciamento Flexível:</strong> <a class="header-anchor" href="#gerenciamento-flexivel" aria-label="Permalink to &quot;**Gerenciamento Flexível:**&quot;">​</a></h4><ul><li><strong>Editar:</strong> Altere uma transação e escolha se a mudança afeta todas as recorrências ou apenas algumas.</li><li><strong>Excluir:</strong> Remova uma única transação ou toda a série de recorrências.</li></ul><p><a href="/features/transactions-recurrences.html">Leia o guia completo sobre Transações Recorrentes</a></p><h2 id="📊-visualizacao-de-saldos" tabindex="-1">📊 Visualização de Saldos <a class="header-anchor" href="#📊-visualizacao-de-saldos" aria-label="Permalink to &quot;📊 Visualização de Saldos&quot;">​</a></h2><img src="'+s+'" width="600px" style="padding-bottom:10px;"><img src="'+t+'" width="350px"><h3 id="o-que-sao-saldos-personalizados" tabindex="-1"><strong>O que são Saldos Personalizados?</strong> <a class="header-anchor" href="#o-que-sao-saldos-personalizados" aria-label="Permalink to &quot;**O que são Saldos Personalizados?**&quot;">​</a></h3><p>Saldos permitem que você faça cálculos personalizados entre grupos, categorias ou subcategorias.</p><h4 id="exemplo-pratico-1" tabindex="-1"><strong>Exemplo Prático:</strong> <a class="header-anchor" href="#exemplo-pratico-1" aria-label="Permalink to &quot;**Exemplo Prático:**&quot;">​</a></h4><ol><li>Crie um saldo chamado <strong>Economia Mensal</strong>.</li><li>Some todas as suas <strong>Receitas</strong> e subtraia os <strong>Gastos</strong>.</li><li>Acompanhe quanto você está economizando a cada mês.</li></ol><h4 id="beneficios" tabindex="-1"><strong>Benefícios:</strong> <a class="header-anchor" href="#beneficios" aria-label="Permalink to &quot;**Benefícios:**&quot;">​</a></h4><ul><li>Entenda melhor sua saúde financeira.</li><li>Tome decisões informadas com base em dados claros.</li></ul><p><a href="/features/balances.html">Leia o guia completo sobre Visualização de Saldos</a></p><h2 id="📈-fluxo-de-caixa" tabindex="-1">📈 Fluxo de Caixa <a class="header-anchor" href="#📈-fluxo-de-caixa" aria-label="Permalink to &quot;📈 Fluxo de Caixa&quot;">​</a></h2><p>Acompanhe sua saúde financeira em um só lugar:</p><ul><li><strong>Gráfico mensal:</strong> entradas vs. saídas por mês no ano.</li><li><strong>Análise por categoria:</strong> totais e principais transações (Essencial+) e relatórios avançados com comparativo e variação (Equilíbrio Total).</li><li><strong>Projeções:</strong> saldo projetado com base na sua média mensal.</li><li><strong>Exportação XLSX:</strong> exporte suas transações e análises para Excel (Equilíbrio Total).</li></ul><p><a href="/features/cashflow.html">Leia o guia completo do Fluxo de Caixa</a></p><h2 id="📚-guias-detalhados" tabindex="-1">📚 Guias Detalhados <a class="header-anchor" href="#📚-guias-detalhados" aria-label="Permalink to &quot;📚 Guias Detalhados&quot;">​</a></h2><p>Prefere ler? Nossos guias escritos cobrem todas as funcionalidades do FlyCash em detalhes, com exemplos práticos e dicas úteis.</p><ul><li><a href="/features/groups-and-categories.html">Guia Completo de Grupos e Categorias</a></li><li><a href="/features/transactions.html">Tudo sobre Transações</a></li><li><a href="/features/transactions-recurrences.html">Tudo sobre Transações Recorrentes</a></li><li><a href="/features/balances.html">Dominando a Visualização de Saldos</a></li><li><a href="/features/import-transactions.html">Importação de Faturas (PDF/OFX)</a></li><li><a href="/features/cashflow.html">Fluxo de Caixa</a></li></ul><h2 id="🚀-dicas-rapidas" tabindex="-1">🚀 Dicas Rápidas <a class="header-anchor" href="#🚀-dicas-rapidas" aria-label="Permalink to &quot;🚀 Dicas Rápidas&quot;">​</a></h2><ul><li>Use <strong>categorias específicas</strong> para entender melhor seus gastos.</li><li><u>Desabilite</u> o <strong>lembrete de pagamento</strong> em receitas que não estão sob seu controle para evitar alarmes falsos de atrasos. Use apenas o status para acompanhar o progresso.</li><li>Configure <strong>transações recorrentes</strong> para contas fixas e nunca mais se esqueça de pagá-las.</li><li><strong>Importe a fatura</strong> do cartão para economizar horas de digitação manual.</li><li>Crie <strong>saldos personalizados</strong> para acompanhar metas financeiras, como economias ou investimentos.</li></ul><hr><h3 id="por-que-escolher-o-flycash" tabindex="-1"><strong>Por que Escolher o FlyCash?</strong> <a class="header-anchor" href="#por-que-escolher-o-flycash" aria-label="Permalink to &quot;**Por que Escolher o FlyCash?**&quot;">​</a></h3><ul><li><strong>Simplicidade:</strong> Interface intuitiva e fácil de usar.</li><li><strong>Flexibilidade:</strong> Registre gastos na hora ou importe tudo de uma vez.</li><li><strong>Controle Total:</strong> Entenda para onde vai seu dinheiro com relatórios e gráficos.</li></ul><p><a href="https://flyca.sh" target="_blank" rel="noreferrer">Experimente Grátis 💸</a></p><hr><h3 id="proximos-passos" tabindex="-1"><strong>Próximos Passos</strong> <a class="header-anchor" href="#proximos-passos" aria-label="Permalink to &quot;**Próximos Passos**&quot;">​</a></h3><ul><li><a href="/getting-started.html">Comece agora com o FlyCash</a></li><li><a href="/plans-and-pricing.html">Explore nossos planos e preços</a></li><li><a href="/faq.html">Dúvidas? Consulte o FAQ</a></li></ul>',59)]))}const _=i(u,[["render",d]]);export{C as __pageData,_ as default};
